    -- De-obfuscate string constants using rolling PRNG keystream
    local function decodeString(bytes, key)
        local chars = {}
        local k = key
        for i = 1, #bytes do
            k = (k * 33 + (i - 1) + 7) % 256
            local b = bytes[i]
            local curK = k
            -- Bitwise XOR in pure Lua 5.1 without bit library
            local res = 0
            local p = 1
            for _ = 1, 8 do
                local b1 = b % 2
                local b2 = curK % 2
                if b1 ~= b2 then res = res + p end
                b = mFloor(b / 2)
                curK = mFloor(curK / 2)
                p = p * 2
            end
            chars[i] = sChar(res)
        end
        return tConcat(chars)
    end

    local function prepareConstants(proto)
        local consts = {}
        local strKey = proto.strKey or 137
        for i = 1, #proto.constants do
            local item = proto.constants[i]
            if item.type == "NUM" then
                consts[i - 1] = item.val
            elseif item.type == "STR_ENC" then
                consts[i - 1] = decodeString(item.val, strKey)
            elseif item.type == "BOOL" then
                consts[i - 1] = (item.val == 1)
            elseif item.type == "NIL" then
